  ('ismp-abbreviations', 73, 'Institute for Safe Medication Practices Error-Prone Abbreviations (ISMP Error-Prone Abbreviations)', 'ISMP List of Error-Prone Abbreviations, Symbols, and Dose Designations', 'https://home.ecri.org/blogs/guidance-insights-tools/list-of-error-prone-abbreviations', 'Institute for Safe Medication Practices (ISMP)', 2024, 'The ISMP List of Error-Prone Abbreviations, Symbols, and Dose Designations contains abbreviations, symbols, and dose designations which have been reported through the ISMP National Medication Errors Reporting Program (ISMP MERP) and have been misinterpreted and involved in harmful or potentially harmful medication errors. These abbreviations, symbols, and dose designations should NEVER be used when communicating medical information verbally, electronically, and/or in handwritten applications. This includes internal communications; verbal, handwritten, or electronic prescriptions; handwritten and computer-generated medication labels; drug storage bin labels; medication administration records; and screens associated with pharmacy and prescriber computer order entry systems, automated dispensing cabinets, smart infusion pumps, and other medication-related technologies.', 'Copyrighted', NULL, 'Source datasets', 'Safety, toxicology, and public health', NULL, 'Institute for Safe Medication Practices (ISMP). (2024). ISMP list of error-prone abbreviations, symbols, and dose designations. https://home.ecri.org/blogs/guidance-insights-tools/list-of-error-prone-abbreviations', '{"kind": "web", "title": "ISMP List of Error-Prone Abbreviations, Symbols, and Dose Designations", "publisher": "Institute for Safe Medication Practices (ISMP)", "nlmPublisher": "Institute for Safe Medication Practices (ISMP)"}'::jsonb, NULL),
